def seed_full_year(apps, schema_editor):
    """补数据（幂等）—— 已存在的条目跳过，不会重复插入。"""
    CalendarTask = apps.get_model('api', 'CalendarTask')
    created = skipped = 0
    for crop_type, month, task_type, title, detail, title_en, detail_en in TEMPLATE:
        _, is_new = CalendarTask.objects.get_or_create(
            crop_type=crop_type, month=month, title=title,
            defaults={
                'task_type': task_type,
                'detail': detail,
                'title_en': title_en,
                'detail_en': detail_en,
                'source': '通用模板',
                'is_active': True,
            },
        )
        created += 1 if is_new else 0
        skipped += 0 if is_new else 1
    print(f'    日历模板补全：新增 {created} 条，已存在 {skipped} 条，清单共 {len(TEMPLATE)} 条')


def unseed_full_year(apps, schema_editor):
    """回滚**只删本迁移加的那些**。

    ⚠️ 不能像 0029 那样 `filter(source='通用模板').delete()` ——
    那会把 0029 的 40 条基础模板一起删掉。按 (作物, 月份, 标题) 精确删除。
    """
    CalendarTask = apps.get_model('api', 'CalendarTask')
    removed = 0
    for crop_type, month, _type, title, _d, _te, _de in TEMPLATE:
        removed += CalendarTask.objects.filter(
            crop_type=crop_type, month=month, title=title, source='通用模板',
        ).delete()[0]
    print(f'    日历模板补全回滚：删除 {removed} 条')


class Migration(migrations.Migration):

    dependencies = [
        ('api', '0057_assistantmessage_truncated'),
    ]

    operations = [
        migrations.RunPython(seed_full_year, unseed_full_year),
    ]
